export class TopUp extends Offering {
    static readonly logger = new Logger(TopUp.name);
    public topUpAmount: number;
    public topUpThreshold: number;
    private creditService: CreditService;

    async enroll(subject: string, customer?: ReadCustomerResponseData): Promise<void> {
        // Register the hourly top-up scheduler for this offering (one per offering, not per customer)
        await this.registerTopUpScheduler(subject);
        // Run initial top-up check on enrollment
        await this.topUp({ customer: customer! });
    }

    async unenroll({
        customer,
        shouldCreditRemainingPlan,
        isChangeOfPlan,
        creditService,
    }: {
        customer: ReadCustomerResponseData;
        shouldCreditRemainingPlan?: boolean;
        isChangeOfPlan?: boolean;
        creditService?: CreditService;
    }): Promise<void> {
        // Remove the top-up scheduler for this offering
        await this.deregisterTopUpScheduler();
        // Call parent unenroll for any cleanup
        await this.deregisterBillingSchedule();
    }

    async processBilling(
        startDateOverride?: Date,
        endDateOverride?: Date,
        customer?: ReadCustomerResponseData,
        calculateUsage?: boolean,
    ): Promise<string> {
        // Top-up offerings don't generate regular billing invoices
        // Usage is handled via wallet transactions in the hourly check
        return '';
    }

    async offcycleBilling({
        startDate,
        endDate,
        customer,
        invoiceDate,
        invoicePaymentTerm,
        isManual = false,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
        invoiceDate?: string;
        invoicePaymentTerm?: InvoicePaymentTerm;
        isManual?: boolean;
    }): Promise<string> {
        // Top-up offerings don't use offcycle billing
        return '';
    }

    async processFreeTrialEnd({ customer }: { customer: ReadCustomerResponseData }): Promise<string> {
        // Top-up offerings don't have free trials in the traditional sense
        return '';
    }

    async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<void> {
        const creditService = this.creditService || customer.creditService;
        if (!creditService) {
            TopUp.logger.warn(`No credit service available for top-up check for customer ${customer.customerId}`);
            return;
        }

        const { balance } = await creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: customer.customerId,
        });
        const currentBalance = parseFloat(balance);
        const thresholdAmount = this.topUpAmount * this.topUpThreshold;

        TopUp.logger.log(
            `Top-up check for customer ${customer.customerId}: balance=${currentBalance}, threshold=${thresholdAmount}, topUpAmount=${this.topUpAmount}`,
        );

        // Treat balance exactly at threshold as sufficient
        if (currentBalance >= thresholdAmount) {
            TopUp.logger.log(`Balance ${currentBalance} is at or above threshold ${thresholdAmount}, no top-up needed`);
            return;
        }

        // Calculate the gap to topUpAmount
        const gap = this.topUpAmount - currentBalance;
        TopUp.logger.log(`Balance ${currentBalance} is below threshold ${thresholdAmount}, creating top-up invoice for $${gap}`);

        // Create invoice with storePaymentAsCredit: true
        const lineItems = new InvoiceLineItems();
        lineItems.addLineItem(
            new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, gap),
        );

        await this.invoicesService.create(
            {
                businessID: this.businessID,
                customerId: customer.customerId,
                customer,
                items: lineItems,
                invoiceDate: new Date().toISOString(),
                currency: Offering.getCurrency({ customer, offering: this }),
            },
            false, // isManual = false
        );

        TopUp.logger.log(`Top-up invoice created for customer ${customer.customerId} for $${gap}`);
    }

    private async registerTopUpScheduler(subject: string): Promise<void> {
        if (!this.schedulerService) {
            TopUp.logger.warn('No scheduler service available, cannot register top-up scheduler');
            return;
        }

        const schedulerId = `topup-${this.offeringId}`;
        try {
            await this.schedulerService.create({
                schedulerID: schedulerId,
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                scheduleParameters: {
                    businessID: this.businessID,
                    offeringId: this.offeringId,
                } as CreateBillingReportDto,
                rate: SupportedMeasurementFrequencies.everyHour,
                subject,
                businessID: this.businessID,
            });
            TopUp.logger.log(`Registered top-up scheduler ${schedulerId} for offering ${this.offeringId}`);
        } catch (e) {
            TopUp.logger.error(`Failed to register top-up scheduler: ${e}`);
        }
    }

    private async deregisterTopUpScheduler(): Promise<void> {
        if (!this.schedulerService) {
            return;
        }

        const schedulerId = `topup-${this.offeringId}`;
        try {
            await this.schedulerService.remove({
                schedulerID: schedulerId,
                businessID: this.businessID,
                isBillingQueue: true,
            });
            TopUp.logger.log(`Deregistered top-up scheduler ${schedulerId} for offering ${this.offeringId}`);
        } catch (e) {
            if (e instanceof NotFoundException) {
                TopUp.logger.log(`No top-up scheduler found for ${schedulerId}`);
            } else {
                TopUp.logger.error(`Failed to deregister top-up scheduler: ${e}`);
            }
        }
    }

    constructor({
        offeringName,
        customerId,
        invoicesService,
        schedulerService,
        dimensions,
        businessID,
        customerService,
        freeTrialLength,
        freeTrialEndDate,
        billingCycle,
        currency,
        settings,
        minimumCharge,
        usageOverrides,
        dimensionOverrides,
        offeringId,
        creditService,
        topUpAmount,
        topUpThreshold,
    }: {
        offeringName: string;
        businessID: string;
        customerId: string;
        invoicesService: InvoicesService;
        schedulerService?: SchedulerService;
        customerService?: CustomerService;
        dimensions: ReadOfferingResponseData['dimensions'];
        freeTrialLength?: string;
        freeTrialEndDate?: string;
        billingCycle?: ValidBillingCycles;
        currency?: SupportedCurrencies;
        settings: ReadSettingsResponseData;
        minimumCharge?: string;
        usageOverrides?: AggregatedUsageResponse[];
        dimensionOverrides?: DimensionOverridesDto[];
        offeringId: string;
        creditService?: CreditService;
        topUpAmount: string;
        topUpThreshold: string;
    }) {
        super({
            offeringType: OfferingType.usageBased,
            offeringName,
            customerId,
            invoicesService,
            schedulerService,
            dimensions,
            businessID,
            customerService,
            freeTrialLength,
            freeTrialEndDate,
            billingCycle,
            currency,
            settings,
            minimumCharge,
            usageOverrides,
            dimensionOverrides,
            offeringId,
        });
        this.topUpAmount = parseFloat(topUpAmount);
        this.topUpThreshold = parseFloat(topUpThreshold || '0.2');
        this.creditService = creditService;
    }
}

