async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<void> {
    const creditService = this.creditService || customer.creditService;
    if (!creditService) {
        TopUp.logger.warn(`No credit service available for top-up check for customer ${customer.customerId}`);
        return;
    }

    // Calculate hourly usage and deduct from wallet
    await this.deductHourlyUsage({ customer, creditService });

    // Now check if top-up is needed
    const { balance } = await creditService.findCreditBalance({
        businessID: this.businessID,
        customerId: customer.customerId,
    });
    const currentBalance = parseFloat(balance);
    const thresholdAmount = this.topUpAmount * this.topUpThreshold;

    TopUp.logger.log(
        `Top-up check for customer ${customer.customerId}: balance=${currentBalance}, threshold=${thresholdAmount}, topUpAmount=${this.topUpAmount}`,
    );

    // Treat balance exactly at threshold as sufficient
    if (currentBalance >= thresholdAmount) {
        TopUp.logger.log(`Balance ${currentBalance} is at or above threshold ${thresholdAmount}, no top-up needed`);
        return;
    }

    // Calculate the gap to topUpAmount
    const gap = this.topUpAmount - currentBalance;
    TopUp.logger.log(`Balance ${currentBalance} is below threshold ${thresholdAmount}, creating top-up invoice for $${gap}`);

    // Create invoice with storePaymentAsCredit: true
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(
        new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, gap),
    );

    await this.invoicesService.create(
        {
            businessID: this.businessID,
            customerId: customer.customerId,
            customer,
            items: lineItems,
            invoiceDate: new Date().toISOString(),
            currency: Offering.getCurrency({ customer, offering: this }),
        },
        false, // isManual = false
    );

    TopUp.logger.log(`Top-up invoice created for customer ${customer.customerId} for $${gap}`);
}

private async deductHourlyUsage({ customer, creditService }: { customer: ReadCustomerResponseData; creditService: CreditService }): Promise<void> {
    const endDate = new Date();
    const startDate = new Date(endDate.getTime() - 60 * 60 * 1000); // 1 hour ago

    TopUp.logger.log(`Calculating hourly usage for customer ${customer.customerId} from ${startDate.toISOString()} to ${endDate.toISOString()}`);

    // Get usage for the past hour
    const usageResponse = await this.customerService.findUsageForCustomer(
        {
            businessID: this.businessID,
            customerId: customer.customerId,
            customer,
        },
        {
            startTime: startDate.toISOString(),
            endTime: endDate.toISOString(),
            aggregationPurpose: 'BILLING',
        },
    );

    const usageData = usageResponse.data as any[];
    if (!usageData || usageData.length === 0) {
        TopUp.logger.log(`No usage data for customer ${customer.customerId} in the past hour`);
        return;
    }

    // Calculate the cost of usage for each dimension
    let totalUsageCost = 0;
    let exchangeRate = 1;

    if (Offering.getCurrency({ customer, offering: this }) !== SupportedCurrencies.USD) {
        exchangeRate = await AnalyticsService.getExchangeRate({
            currency: Offering.getCurrency({ customer, offering: this }),
        });
    }

    for (const usageElement of usageData) {
        const dimension = this.dimensions.find((d) => d.dimensionId === usageElement.dimensionId);
        if (!dimension) continue;

        // Calculate total usage for this dimension
        const totalUsage = Billing.usageToTotal(usageElement, dimension);
        const usageAmount = parseFloat(totalUsage);

        if (usageAmount <= 0) continue;

        // Calculate unit cost
        let unitCost = 0;
        if (dimension.consumptionPrice !== undefined && dimension.consumptionPrice !== null) {
            unitCost = parseFloat(dimension.consumptionPrice) * exchangeRate;
        } else if (dimension.tiers && dimension.tiers.length > 0) {
            // For tiered pricing, we need to calculate based on tiers
            // Simplified: use the first tier's unit price
            const firstTier = dimension.tiers[0];
            if (firstTier?.unitPrice) {
                unitCost = parseFloat(firstTier.unitPrice) * exchangeRate;
            }
        }

        if (unitCost > 0) {
            const dimensionCost = usageAmount * unitCost;
            totalUsageCost += dimensionCost;
            TopUp.logger.log(`Dimension ${dimension.dimensionId}: usage=${usageAmount}, unitCost=${unitCost}, cost=${dimensionCost}`);
        }
    }

    if (totalUsageCost > 0) {
        // Deduct usage cost from wallet as a negative credit transaction
        TopUp.logger.log(`Deducting hourly usage cost $${totalUsageCost.toFixed(2)} from wallet for customer ${customer.customerId}`);
        await creditService.create(
            {
                transactionAmount: (-totalUsageCost).toFixed(2),
                businessID: this.businessID,
                customerId: customer.customerId,
                metadata: {
                    reason: `Hourly usage deduction for ${this.offeringName}`,
                    offeringId: this.offeringId,
                    type: 'usage_deduction',
                },
                timestamp: new Date().toISOString(),
            },
            false, // Don't validate customer again
        );
    } else {
        TopUp.logger.log(`Zero usage cost for customer ${customer.customerId}, no credit transaction created`);
    }
}

