    const thresholdAmount = this.topUpAmount * this.topUpThreshold;

    TopUp.logger.log(
        `Top-up check for customer ${customer.customerId}: balance=${currentBalance}, threshold=${thresholdAmount}, topUpAmount=${this.topUpAmount}`,
    );

    // Treat balance exactly at threshold as sufficient
    if (currentBalance >= thresholdAmount) {
        TopUp.logger.log(`Balance ${currentBalance} is at or above threshold ${thresholdAmount}, no top-up needed`);
        return;
    }

    // Calculate the gap to topUpAmount
    const gap = this.topUpAmount - currentBalance;
    TopUp.logger.log(`Balance ${currentBalance} is below threshold ${thresholdAmount}, creating top-up invoice for $${gap}`);

    // Create invoice with storePaymentAsCredit: true
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(
        new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, gap),
    );

    await this.invoicesService.create(
        {
            businessID: this.businessID,
            customerId: customer.customerId,
            customer,
            items: lineItems,
            invoiceDate: new Date().toISOString(),
            currency: Offering.getCurrency({ customer, offering: this }),
        },
        false, // isManual = false
    );

    TopUp.logger.log(`Top-up invoice created for customer ${customer.customerId} for $${gap}`);
}

