private async processTopUpCheck({ offeringId, businessID }: { offeringId: string; businessID: string }): Promise<void> {
    BillingService.logger.log(`Processing top-up check for offering ${offeringId} in business ${businessID}`);
    try {
        // Find all customers enrolled in this offering
        const { data: customers } = await this.customerService.findAllCustomersWithOfferingId({
            businessID,
            offeringId,
        });

        if (!customers.length) {
            BillingService.logger.log(`No customers found for offering ${offeringId}`);
            return;
        }

        // Get the offering config for each customer
        for (const customer of customers) {
            try {
                const contract = await this.contractService.findOne({
                    customerId: customer.customerId,
                    offeringId,
                    businessID,
                });
                if (!contract?.offering) {
                    continue;
                }

                const offering = contract.offering;
                // Check if this is a top-up offering
                if (offering.billingCycle === ValidBillingCycles.topUp && typeof offering.topUp === 'function') {
                    BillingService.logger.log(`Running top-up check for customer ${customer.customerId} on offering ${offeringId}`);
                    await offering.topUp({ customer: customer as any, creditService: this.invoicesService['creditService'] });
                }
            } catch (customerError) {
                BillingService.logger.error(`Failed to process top-up for customer ${customer.customerId}: ${customerError}`);
                AuditService.publishEvent({
                    message: 'Failed to process top-up check for customer',
                    topic: AuditScope.ERROR,
                    data: [{ error: serializeError(customerError), customerId: customer.customerId, offeringId, businessID }],
                });
            }
        }
    } catch (error) {
        BillingService.logger.error(`Failed to process top-up check for offering ${offeringId}: ${error}`);
        AuditService.publishEvent({
            message: 'Failed to process top-up check',
            topic: AuditScope.ERROR,
            data: [{ error: serializeError(error), offeringId, businessID }],
        });
    }
}

