export class TopUp extends Offering {
    static readonly logger = new Logger(TopUp.name);
    public topUpAmount: number;
    public topUpThreshold: number;

    async enroll(subject: string, customer?: ReadCustomerResponseData, creditService?: CreditService): Promise<void> {
        // Register the hourly top-up scheduler for this offering (one per offering, not per customer)
        await this.registerTopUpScheduler(subject);
        // Run initial top-up check on enrollment
        if (creditService) {
            await this.topUp({ customer: customer!, creditService });
        }
    }

    async unenroll({
        customer,
        shouldCreditRemainingPlan,
        isChangeOfPlan,
        creditService,
    }: {
        customer: ReadCustomerResponseData;
        shouldCreditRemainingPlan?: boolean;
        isChangeOfPlan?: boolean;
        creditService?: CreditService;
    }): Promise<void> {
        // Remove the top-up scheduler for this offering
        await this.deregisterTopUpScheduler();
        // Call parent unenroll for any cleanup
        await this.deregisterBillingSchedule();
    }

    async processBilling(
        startDateOverride?: Date,
        endDateOverride?: Date,
        customer?: ReadCustomerResponseData,
        calculateUsage?: boolean,
    ): Promise<string> {
        // Top-up offerings don't generate regular billing invoices
        // Usage is handled via wallet transactions in the hourly check
        return '';
    }

    async offcycleBilling({
        startDate,
        endDate,
        customer,
        invoiceDate,
        invoicePaymentTerm,
        isManual = false,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
        invoiceDate?: string;
        invoicePaymentTerm?: InvoicePaymentTerm;
        isManual?: boolean;
    }): Promise<string> {
        // Top-up offerings don't use offcycle billing
        return '';
    }

    async processFreeTrialEnd({ customer }: { customer: ReadCustomerResponseData }): Promise<string> {
        // Top-up offerings don't have free trials in the traditional sense
        return '';
    }

    async topUp({ customer, creditService }: { customer: ReadCustomerResponseData; creditService: CreditService }): Promise<void> {
        if (!creditService) {
            TopUp.logger.warn(`No credit service available for top-up check for customer ${customer.customerId}`);
            return;
        }

        // Calculate hourly usage and deduct from wallet
        await this.deductHourlyUsage({ customer, creditService });

        // Now check if top-up is needed
        const { balance } = await creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: customer.customerId,
        });
        const currentBalance = parseFloat(balance);
        const thresholdAmount = this.topUpAmount * this.topUpThreshold;

        TopUp.logger.log(
            `Top-up check for customer ${customer.customerId}: balance=${currentBalance}, threshold=${thresholdAmount}, topUpAmount=${this.topUpAmount}`,
        );

        // Treat balance exactly at threshold as sufficient
        if (currentBalance >= thresholdAmount) {
            TopUp.logger.log(`Balance ${currentBalance} is at or above threshold ${thresholdAmount}, no top-up needed`);
            return;
        }

        // Calculate the gap to topUpAmount
        const gap = this.topUpAmount - currentBalance;
        TopUp.logger.log(`Balance ${currentBalance} is below threshold ${thresholdAmount}, creating top-up invoice for $${gap}`);

        // Create invoice with storePaymentAsCredit: true
        const lineItems = new InvoiceLineItems();
        lineItems.addLineItem(
            new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, gap),
        );

        await this.invoicesService.create(
            {
                businessID: this.businessID,
                customerId: customer.customerId,
                customer,
                items: lineItems,
                invoiceDate: new Date().toISOString(),
                currency: Offering.getCurrency({ customer, offering: this }),
            },
            false, // isManual = false
        );

        TopUp.logger.log(`Top-up invoice created for customer ${customer.customerId} for $${gap}`);
    }

    private async deductHourlyUsage({ customer, creditService }: { customer: ReadCustomerResponseData; creditService: CreditService }): Promise<void> {
        const endDate = new Date();
        const startDate = new Date(endDate.getTime() - 60 * 60 * 1000); // 1 hour ago

        TopUp.logger.log(`Calculating hourly usage for customer ${customer.customerId} from ${startDate.toISOString()} to ${endDate.toISOString()}`);

        // Get usage for the past hour
        const usageResponse = await this.customerService.findUsageForCustomer(
            {
                businessID: this.businessID,
                customerId: customer.customerId,
                customer,
            },
            {
                startTime: startDate.toISOString(),
                endTime: endDate.toISOString(),
                aggregationPurpose: AggregationPurpose.BILLING,
            },
        );

        const usageData = usageResponse.data as any[];
        if (!usageData || usageData.length === 0) {
            TopUp.logger.log(`No usage data for customer ${customer.customerId} in the past hour`);
            return;
        }

        // Calculate the cost of usage for each dimension
        let totalUsageCost = 0;
        let exchangeRate = 1;

        if (Offering.getCurrency({ customer, offering: this }) !== SupportedCurrencies.USD) {
            exchangeRate = await AnalyticsService.getExchangeRate({
                currency: Offering.getCurrency({ customer, offering: this }),
            });
        }

        for (const usageElement of usageData) {
            const dimension = this.dimensions.find((d) => d.dimensionId === usageElement.dimensionId);
            if (!dimension) continue;

            // Calculate total usage for this dimension
            const totalUsage = Billing.usageToTotal(usageElement, dimension);
            const usageAmount = parseFloat(totalUsage);

            if (usageAmount <= 0) continue;

            // Calculate unit cost
            let unitCost = 0;
            if (dimension.consumptionPrice !== undefined && dimension.consumptionPrice !== null) {
                unitCost = parseFloat(dimension.consumptionPrice) * exchangeRate;
            } else if (dimension.tiers && dimension.tiers.length > 0) {
                // For tiered pricing, we need to calculate based on tiers
                // Simplified: use the first tier's unit price
                const firstTier = dimension.tiers[0];
                if (firstTier?.unitPrice) {
                    unitCost = parseFloat(firstTier.unitPrice) * exchangeRate;
                }
            }

            if (unitCost > 0) {
                const dimensionCost = usageAmount * unitCost;
                totalUsageCost += dimensionCost;
                TopUp.logger.log(`Dimension ${dimension.dimensionId}: usage=${usageAmount}, unitCost=${unitCost}, cost=${dimensionCost}`);
            }
        }

        if (totalUsageCost > 0) {
            // Deduct usage cost from wallet as a negative credit transaction
            TopUp.logger.log(`Deducting hourly usage cost $${totalUsageCost.toFixed(2)} from wallet for customer ${customer.customerId}`);
            await creditService.create(
                {
                    transactionAmount: (-totalUsageCost).toFixed(2),
                    businessID: this.businessID,
                    customerId: customer.customerId,
                    metadata: {
                        reason: `Hourly usage deduction for ${this.offeringName}`,
                        offeringId: this.offeringId,
                        type: 'usage_deduction',
                    },
                    timestamp: new Date().toISOString(),
                },
                false, // Don't validate customer again
            );
        } else {
            TopUp.logger.log(`Zero usage cost for customer ${customer.customerId}, no credit transaction created`);
        }
    }

    private async registerTopUpScheduler(subject: string): Promise<void> {
        if (!this.schedulerService) {
            TopUp.logger.warn('No scheduler service available, cannot register top-up scheduler');
            return;
        }

        const schedulerId = `topup-${this.offeringId}`;
        try {
            await this.schedulerService.create({
                schedulerID: schedulerId,
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                scheduleParameters: {
                    businessID: this.businessID,
                    offeringId: this.offeringId,
                } as CreateBillingReportDto,
                rate: SupportedMeasurementFrequencies.everyHour,
                subject,
                businessID: this.businessID,
            });
            TopUp.logger.log(`Registered top-up scheduler ${schedulerId} for offering ${this.offeringId}`);
        } catch (e) {
            TopUp.logger.error(`Failed to register top-up scheduler: ${e}`);
        }
    }

    private async deregisterTopUpScheduler(): Promise<void> {
        if (!this.schedulerService) {
            return;
        }

        const schedulerId = `topup-${this.offeringId}`;
        try {
            await this.schedulerService.remove({
                schedulerID: schedulerId,
                businessID: this.businessID,
                isBillingQueue: true,
            });
            TopUp.logger.log(`Deregistered top-up scheduler ${schedulerId} for offering ${this.offeringId}`);
        } catch (e) {
            if (e instanceof NotFoundException) {
                TopUp.logger.log(`No top-up scheduler found for ${schedulerId}`);
            } else {
                TopUp.logger.error(`Failed to deregister top-up scheduler: ${e}`);
            }
        }
    }

    constructor({
        offeringName,
        customerId,
        invoicesService,
        schedulerService,
        dimensions,
        businessID,
        customerService,
        freeTrialLength,
        freeTrialEndDate,
        billingCycle,
        currency,
        settings,
        minimumCharge,
        usageOverrides,
        dimensionOverrides,
        offeringId,
        topUpAmount,
        topUpThreshold,
    }: {
        offeringName: string;
        businessID: string;
        customerId: string;
        invoicesService: InvoicesService;
        schedulerService?: SchedulerService;
        customerService?: CustomerService;
        dimensions: ReadOfferingResponseData['dimensions'];
        freeTrialLength?: string;
        freeTrialEndDate?: string;
        billingCycle?: ValidBillingCycles;
        currency?: SupportedCurrencies;
        settings: ReadSettingsResponseData;
        minimumCharge?: string;
        usageOverrides?: AggregatedUsageResponse[];
        dimensionOverrides?: DimensionOverridesDto[];
        offeringId: string;
        topUpAmount: string;
        topUpThreshold: string;
    }) {
        super({
            offeringType: OfferingType.usageBased,
            offeringName,
            customerId,
            invoicesService,
            schedulerService,
            dimensions,
            businessID,
            customerService,
            freeTrialLength,
            freeTrialEndDate,
            billingCycle,
            currency,
            settings,
            minimumCharge,
            usageOverrides,
            dimensionOverrides,
            offeringId,
        });
        this.topUpAmount = parseFloat(topUpAmount);
        this.topUpThreshold = parseFloat(topUpThreshold || '0.2');
    }
}

